const TEAM_ROLES={attending:'Doctor on duty',primaryNurse:'Primary nurse',care:'Ward doctor',nurse:'Nurse'};
const teamOf=c=>{const s=c.state,now=s.demoClock||'2026-08-31T09:00',seen=new Set();
 return (s.relationships||[]).filter(r=>r.p===c.patient.id&&r.active&&TEAM_ROLES[r.role]&&onDuty(s.people[r.actor],now))
  .sort((a,b)=>Object.keys(TEAM_ROLES).indexOf(a.role)-Object.keys(TEAM_ROLES).indexOf(b.role)).filter(r=>!seen.has(r.actor)&&seen.add(r.actor));};
const pinTeam=c=>{const s=c.state,p=c.patient,rows=teamOf(c),shown=[p.attending,carer(s,p.id,'primaryNurse')],extra=rows.filter(r=>!shown.includes(s.people[r.actor]?.name)).length;if(!extra)return '';
 return `<details class="pin-pop pin-team"><summary class="button tertiary" aria-label="Care team on duty" title="Care team on duty"><span data-no-i18n>+${extra}</span></summary><div class="pin-pop-panel"><p class="pin-pop-title">Care team on duty</p><ul class="team-list">${rows.map(r=>`<li><strong data-no-i18n>${E(s.people[r.actor]?.name)}</strong><small><span>${E(TEAM_ROLES[r.role])}</span> · <span>${E(s.people[r.actor]?.department||'')}</span></small></li>`).join('')}</ul></div></details>`;};
