 const may=W.canSurgery(s,p.id,r.actor)&&!frozen(c);const prior=r.editSurgery&&r.editSurgery!=='new'?all.find(x=>x.id===r.editSurgery):null;
 const rows=latest.map(x=>{const id='sg-'+x.id;const primary=(x.surgeons||[]).find(v=>v.role==='primary')?.name||'';return `<tr><td class="col-date">${E(fmt(x.performedAt||x.start))}</td><td><strong>${E(x.procedure)}</strong></td><td>${E(surgeryValue(x,'category'))||'—'}</td><td>${E(x.anesthesia||'—')}</td><td>${E(primary||'—')}</td><td>${E(s.people[x.author]?.name||x.author)}<span class="source">${E(fmt(x.at))}</span></td><td>v${x.version}</td><td class="row"><button type="button" class="secondary compact-button" data-disclosure-toggle="${E(id)}" aria-expanded="false" aria-controls="${E(id)}">Details</button>${may?nav(c,'rounds','Revise',{editSurgery:x.id}):''}${pbtn('surgery',x.id)}</td></tr><tr id="${E(id)}" class="surgery-detail-row" hidden><td colspan="8">${surgeryDetail(x)}${x.reason?`<p>Reason for revision: ${E(x.reason)}</p>`:''}<p class="source">${E(x.source||'')} · ${E(x.form||'')}</p>${may?voidAction(c,'surgery',x,true):''}</td></tr>`;}).join('');
