function handoverHistory(c,pid){const s=c.state,r=c.route;const list=s.handovers.filter(x=>x.p===pid||!x.p&&(x.tasks||[]).some(t=>t.p===pid));const sealed=W.archiveState(s,pid)==='sealed';
 return list.slice().reverse().map(x=>{const replaced=list.some(v=>v.replaces===x.id),receipt=s.receipts.find(v=>v.handover===x.id);return `<article class="workflow-record"><div class="row between"><h3>${E(s.people[x.author]?.name)} → ${E(s.people[x.receiver]?.name)}</h3><span class="pill ${replaced||receipt?'':'warning'}">v${x.version} · ${replaced?'Superseded':receipt?'Accepted':'Awaiting acceptance'}</span></div><p class="preserve-lines">${E(x.summary)}</p><small>Scheduled shift end ${E(x.scheduled||s.people[x.author]?.end)} · Handed over ${E(fmt(x.clinicalAt||x.at))}${receipt?' · Accepted '+E(s.people[receipt.actor]?.name||'')+' '+E(fmt(receipt.clinicalAt||receipt.at)):''}${x.batch?' · Sent with shift batch '+E(x.batch):''}</small>${x.reason?'<p>Reason for amendment: '+E(x.reason)+'</p>':''}<div class="row">${ui('print','Print preview',{printType:'handover',printId:x.id,p:pid})}${!replaced&&!receipt&&x.receiver===r.actor&&!sealed?c.act('receive','Accept handover and take over open tasks',{id:x.id,p:pid,encounter:'ENC-'+pid}):''}</div></article>`;}).join('')||empty('No handover versions for this patient yet.');}
const orderDay=o=>String(o.orderedAt||o.start||'').slice(0,10);
