 const head=[confirmed?'<input type="checkbox" id="hv-all" aria-label="Select all patients this shift">':'<span class="hv-head-pick">Select</span>','Bed / patient','Diagnosis','Active Order List','Incoming '+(doctor?'Doctor':'Nurse'),doctor?'Handover ISBAR':'Handover SBAR'];
 const receiveBlock=incoming.length?card('Handed to me by previous shift ('+incoming.length+')',incoming.map(({h,x})=>`<article class="workflow-record"><div class="row between"><h3>${E(x.patient.bed)} ${E(x.patient.name)} · ${E(s.people[h.author]?.name)} v${h.version}</h3><span class="pill warning">Awaiting acceptance</span></div><p class="preserve-lines">${E(h.summary)}</p><small>Handed over ${E(fmt(h.clinicalAt||h.at))} · Open tasks taken over ${(h.tasks||[]).length} · Active orders ${(h.orders||[]).length}</small><div class="row">${c.act('receive','Accept',{id:h.id,p:x.p,encounter:'ENC-'+x.p},false,incoming.length>1)}</div></article>`).join(''),incoming.length>1?ui('receiveAll','Accept all',{items:incoming.map(({h,x})=>({id:h.id,p:x.p}))},true):''):'';
 const tableHtml=`<div class="table-wrap handover-table${doctor?' handover-doctor':' handover-nurse'}"><table><thead><tr>${head.map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>handoverRow(c,x,doctor,confirmed,today)).join('')}</tbody></table></div>`;
 const endAt=(a.end&&a.end.includes('+1')?'2026-09-01T':'2026-08-31T')+String(a.end||'15:30').replace('+1','').slice(0,5);
 const receivers=T.receivers(s,r.actor).map(([id,label])=>[id,label+(rows.every(x=>doctor?W.canWrite(s,x.p,id):W.canNurse(s,x.p,id))?' · already caring for all patients this shift':' · patients not yet in your care will be taken over at handover')]);
 
 const staged=rows.filter(x=>x.draft.receiver).length;
 // 功能列釘在最上面：整批交給誰、暫存給勾選的病人、交班時間、送出交班；表格往下捲不會把它捲掉。
