 const ctxBar=`<div class="handover-context"><span>${doctor?'Doctor handover':'Nurse handover'} · This shift ${E((root.ICUClinical.shiftTimes(a)||['—'])[0])}–${E((root.ICUClinical.shiftTimes(a)||['','—'])[1])}</span><span>Patients in care <b>${rows.length}</b></span><span>Handed over <b>${rows.filter(x=>x.latestOut).length}</b></span><span>Accepted <b>${rows.filter(x=>x.receipt).length}</b></span><span>Awaiting my acceptance <b>${incoming.length}</b></span></div>`;
 const intro=`Select patients and click “Save draft for selected” to assign the incoming ${doctor?'Doctor':'Nurse'}; rows without their own assignment go to “Hand over all to” when you click “Submit handover”.`;
 const main=card(doctor?'Doctor handover sheet (ISBAR)':'Nurse handover sheet (SBAR)',`<p class="muted">${intro}</p>${ctxBar}${rows.length?(confirmed?c.form('handoverPublishBatch',bar+tableHtml,'',{p:''}):`<div class="notice">Care roster not yet confirmed; below is a read-only preview. Confirm it to fill in and submit.</div>${tableHtml}`):empty('You have no patients in your care this shift.')}`);
