function signatures(n,s){return [n.signature,n.approvalSignature].filter(Boolean).map(sig=>`<div class="signature-block">${sig.image?`<img src="${E(sig.image)}" alt="Signature image (demo, not a formal e-signature)">`:'<span class="signature-missing">No signature image on file</span>'}<div><strong>${E(s.people[sig.actor]?.name)}</strong><small>${E(fmt(sig.at))}<br>${E(sig.document)} · v${sig.version}<br>Demo identity confirmation</small>${'license' in sig?`<small class="sig-license">${sig.license?`Practice license ${E(sig.license)}`:'No valid practice license on file'}</small>`:''}</div></div>`).join('');}
