 [['devMental','Mental development'],['devMotor','Motor development'],['devOtherIllness','Other illnesses during growth']].forEach(([k,l])=>{if(v(k))out.push([l,v(k),true]);});
 if(v('feedingMethod'))out.push(['Feeding',opt(v('feedingMethod'))]);
